// Modern Composition using CompletableFuture
public CompletableFuture<String> processRequest(String input) {
    return fetchFromDatabase(input)
        .thenApply(this::transformData)
        .thenCompose(this::callExternalService)
        .exceptionally(ex -> "Fallback Value");
}

// Callback Hell (The Anti-Pattern)
public void processRequestLegacy(String input, Callback cb) {
    db.fetch(input, result -> {
        transform(result, transformed -> {
            service.call(transformed, finalResult -> {
                cb.onSuccess(finalResult);
            }, err -> cb.onError(err));
        }, err -> cb.onError(err));
    }, err -> cb.onError(err));
}
